//go:build linux

// Package probe loads the eBPF programs and turns kernel records into
// signals.Event values.
package probe

import (
	"bytes"
	"context"
	"encoding/binary"
	"errors"
	"fmt"
	"log/slog"
	"net/netip"
	"os"
	"strconv"
	"strings"
	"time"

	"github.com/cilium/ebpf"
	"github.com/cilium/ebpf/link"
	"github.com/cilium/ebpf/ringbuf"
	"github.com/cilium/ebpf/rlimit"

	"github.com/mohsinkhanshaik/ebpf-self-healing-agent/internal/signals"
)

// The eBPF objects are generated by `make generate` (bpf2go) into
// agent_bpfel.go / agent_bpfel.o.

// Probe owns the loaded programs and their attachments.
type Probe struct {
	objs     agentObjects
	links    []link.Link
	rd       *ringbuf.Reader
	attached []string
	log      *slog.Logger
}

// Load loads the programs, configures watched process names and attaches
// every hook the kernel supports. It fails only if nothing could attach.
func Load(watchComms []string, log *slog.Logger) (*Probe, error) {
	if err := rlimit.RemoveMemlock(); err != nil {
		return nil, fmt.Errorf("remove memlock rlimit: %w", err)
	}
	p := &Probe{log: log}
	if err := loadAgentObjects(&p.objs, nil); err != nil {
		var ve *ebpf.VerifierError
		if errors.As(err, &ve) {
			return nil, fmt.Errorf("kernel verifier rejected program: %+v", ve)
		}
		return nil, fmt.Errorf("load eBPF objects: %w", err)
	}
	ok := false
	defer func() {
		if !ok {
			p.Close()
		}
	}()

	for _, c := range watchComms {
		var key [16]byte
		copy(key[:15], c)
		if err := p.objs.WatchedComms.Put(key, uint8(1)); err != nil {
			return nil, fmt.Errorf("watch %q: %w", c, err)
		}
	}

	type hook struct {
		name   string
		attach func() (link.Link, error)
	}
	hooks := []hook{
		{"tracepoint/oom/mark_victim", func() (link.Link, error) {
			return link.Tracepoint("oom", "mark_victim", p.objs.HandleOomVictim, nil)
		}},
		{"tracepoint/signal/signal_generate", func() (link.Link, error) {
			return link.Tracepoint("signal", "signal_generate", p.objs.HandleSignalGenerate, nil)
		}},
		{"tracepoint/sched/sched_process_exit", func() (link.Link, error) {
			return link.Tracepoint("sched", "sched_process_exit", p.objs.HandleProcessExit, nil)
		}},
		{"kprobe/tcp_retransmit_skb", func() (link.Link, error) {
			return link.Kprobe("tcp_retransmit_skb", p.objs.HandleRetransmit, nil)
		}},
	}
	for _, h := range hooks {
		l, err := h.attach()
		if err != nil {
			log.Warn("hook unavailable, continuing without it", "hook", h.name, "err", err)
			continue
		}
		p.links = append(p.links, l)
		p.attached = append(p.attached, h.name)
	}
	if len(p.links) == 0 {
		return nil, errors.New("no eBPF hooks could be attached")
	}

	rd, err := ringbuf.NewReader(p.objs.Events)
	if err != nil {
		return nil, fmt.Errorf("open ring buffer: %w", err)
	}
	p.rd = rd
	ok = true
	return p, nil
}

// Attached lists the hooks that are live.
func (p *Probe) Attached() []string { return p.attached }

// Run streams events to out until ctx is cancelled.
func (p *Probe) Run(ctx context.Context, out chan<- signals.Event, pollEvery time.Duration) error {
	go func() {
		<-ctx.Done()
		p.rd.Close()
	}()
	go p.pollRetransmits(ctx, out, pollEvery)

	var raw agentEvent
	for {
		rec, err := p.rd.Read()
		if errors.Is(err, ringbuf.ErrClosed) {
			return nil
		}
		if err != nil {
			return fmt.Errorf("read ring buffer: %w", err)
		}
		if err := binary.Read(bytes.NewReader(rec.RawSample), binary.NativeEndian, &raw); err != nil {
			continue
		}
		ev, ok := decode(raw)
		if !ok {
			continue
		}
		select {
		case out <- ev:
		case <-ctx.Done():
			return nil
		}
	}
}

func decode(raw agentEvent) (signals.Event, bool) {
	ev := signals.Event{
		Time: time.Now(),
		PID:  raw.Pid,
		Comm: cString(raw.Comm[:]),
	}
	switch raw.Kind {
	case 1:
		ev.Kind = signals.OOMKill
		ev.Signal = int(raw.Sig)
		// The tracepoint only carries the victim's PID; it is still alive here.
		ev.Comm = procComm(raw.Pid)
	case 2:
		ev.Kind = signals.CrashSignal
		ev.Signal = int(raw.Sig)
	case 3:
		ev.Kind = signals.ProcessExit
		ev.Signal = int(raw.ExitCode & 0x7f)
		ev.ExitStatus = int((raw.ExitCode >> 8) & 0xff)
	default:
		return ev, false
	}
	return ev, true
}

func (p *Probe) pollRetransmits(ctx context.Context, out chan<- signals.Event, every time.Duration) {
	t := time.NewTicker(every)
	defer t.Stop()
	prev := map[agentConnKey]uint64{}

	for {
		select {
		case <-ctx.Done():
			return
		case <-t.C:
		}

		cur := map[agentConnKey]uint64{}
		var k agentConnKey
		var v uint64
		it := p.objs.Retrans.Iterate()
		for it.Next(&k, &v) {
			cur[k] = v
		}
		if err := it.Err(); err != nil {
			p.log.Warn("iterate retransmit map", "err", err)
			continue
		}

		for key, n := range cur {
			delta := n
			if old, ok := prev[key]; ok && n >= old {
				delta = n - old
			}
			if delta == 0 {
				continue
			}
			ev := signals.Event{
				Kind:  signals.TCPRetransmit,
				Time:  time.Now(),
				Dest:  destString(key),
				Count: delta,
			}
			select {
			case out <- ev:
			case <-ctx.Done():
				return
			}
		}
		prev = cur
	}
}

func destString(k agentConnKey) string {
	var a [4]byte
	binary.NativeEndian.PutUint32(a[:], k.Daddr)
	var pb [2]byte
	binary.NativeEndian.PutUint16(pb[:], k.Dport)
	return netip.AddrPortFrom(netip.AddrFrom4(a), binary.BigEndian.Uint16(pb[:])).String()
}

func procComm(pid uint32) string {
	b, err := os.ReadFile("/proc/" + strconv.FormatUint(uint64(pid), 10) + "/comm")
	if err != nil {
		return ""
	}
	return strings.TrimSpace(string(b))
}

func cString(b []byte) string {
	if i := bytes.IndexByte(b, 0); i >= 0 {
		b = b[:i]
	}
	return string(b)
}

// Close detaches everything and frees kernel resources.
func (p *Probe) Close() error {
	var errs []error
	if p.rd != nil {
		errs = append(errs, p.rd.Close())
	}
	for _, l := range p.links {
		errs = append(errs, l.Close())
	}
	errs = append(errs, p.objs.Close())
	return errors.Join(errs...)
}
